class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_mib = monthly_limit_mib
        self.monthly_limit_bytes = monthly_limit_mib * 1024 * 1024
        # Store files per month: {month: {filename: size_bytes}}
        self.files = {}

    def upload(self, name: str, size_bytes: int, month: str, owner: str = "") -> None:
        if size_bytes == 0:
            raise ValueError("File size cannot be zero")

        # Initialize month entry if it doesn't exist
        if month not in self.files:
            self.files[month] = {}

        # Check if file already exists in this month
        if name in self.files[month]:
            # File already uploaded this month, no change to quota
            return

        # Calculate current usage for this month
        current_usage = self.used_bytes(month)

        # Check if adding this file would exceed the limit
        if current_usage + size_bytes > self.monthly_limit_bytes:
            raise ValueError("Upload would exceed monthly quota")

        # Add the file
        self.files[month][name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        # Only delete if the month and file exist
        if month in self.files and name in self.files[month]:
            del self.files[month][name]

    def used_bytes(self, month: str) -> int:
        # Return total bytes used in the given month
        if month not in self.files:
            return 0
        return sum(self.files[month].values())

    def remaining_bytes(self, month: str) -> int:
        # Return how many bytes can still be uploaded in the month
        return max(0, self.monthly_limit_bytes - self.used_bytes(month))

    def files(self) -> list[str]:
        # Collect all unique file names across all months
        all_files = set()
        for month_files in self.files.values():
            all_files.update(month_files.keys())
        # Return sorted list of file names
        return sorted(list(all_files))

    def files_of(self, owner: str) -> list[str]:
        # Since owner information is not currently tracked in the implementation,
        # this method returns an empty list as there's no owner data stored.
        # In a real implementation, this would require storing owner information
        # with each file, but based on the current structure and requirements,
        # we return an empty list since no owner tracking exists.
        return []
